{
  "name": "tip-and-bill-splitter",
  "version": "1.0.0",
  "private": true,
  "description": "Tip and bill splitter: split a restaurant bill evenly, or by what each person ordered.",
  "type": "module",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "start": "node scripts/serve.js",
    "test": "node --test"
  }
}

// Every fixed message and label the app shows, copied exactly from
// docs/user-stories.md. tests/messages.test.js checks each one against that
// document, so a reworded message fails the tests (D-25).

// Input errors (shared definitions: "Error messages")
export const SUBTOTAL_EMPTY = 'Enter the bill subtotal.';
export const COMMA_OR_CURRENCY = 'Remove commas and currency symbols, e.g. 1250.50.';
export const NEGATIVE = "Amount can't be negative.";
export const NOT_A_NUMBER = 'Enter an amount using digits and an optional decimal point, e.g. 1250.50.';
export const TOO_MANY_DECIMALS = 'Use at most 2 decimal places.';
export const SUBTOTAL_MIN = 'Subtotal must be at least 0.01.';
export const AMOUNT_MAX = "Amount can't be more than 1,000,000.00.";
export const TIP_EMPTY = 'Enter a tip percentage.';
export const TIP_RANGE = 'Tip must be a number from 0 to 100.';
export const PEOPLE_INVALID = 'Number of people must be a whole number from 1 to 50.';
export const ORDERED_MIN = 'Enter what this person ordered (at least 0.01).';

// Other fixed messages (shared definitions: "Other fixed messages")
export const FIX_FIELDS = 'Fix the highlighted fields to see the split.';
export const FILL_IN = 'Fill in the fields above to see the split.';
export const MAX_PEOPLE_NOTE = 'Up to 50 people.';
export const MATCHES_RECEIPT = 'Matches the receipt total.';

// Templates. A = amounts entered, S = receipt subtotal,
// T = receipt total, D = difference. All arguments are formatted strings.
export const warningBelow = (A, S, D) =>
  `The amounts entered add up to ${A}, but the receipt subtotal is ${S}. ${D} is not assigned to anyone.`;
export const warningAbove = (A, D, S) =>
  `The amounts entered add up to ${A}, which is ${D} more than the receipt subtotal of ${S}. Check for an item entered twice.`;
export const totalBelow = (D, T) => `${D} less than the receipt total of ${T}.`;
export const totalAbove = (D, T) => `${D} more than the receipt total of ${T}.`;

// Results-area labels (shared definitions: "Results area")
export const LABEL_SUBTOTAL = 'Subtotal';
export const LABEL_TAX = 'Tax and service charges';
export const labelTip = (percentText) => `Tip (${percentText}%)`;
export const LABEL_TOTAL = 'Total';

// Even-split lines (S-3 display rule)
export const eachPays = (X) => `Each person pays ${X}`;
export const groupPays = (count, X) => (count === 1n ? `1 person pays ${X}` : `${count} people pay ${X}`);
export const sharesAddUp = (count, T) =>
  count === 1n ? `1 share adds up to ${T}` : `${count} shares add up to ${T}`;

// Default label for an unnamed row (shared definitions: "Names")
export const defaultPersonLabel = (position) => `Person ${position}`;

// Money is a BigInt count of cents everywhere in src/lib (D-6, D-19).
// Text is turned into cents by joining digit strings, never through
// floating-point numbers, so "0.1" + "0.2" is exactly 30n cents.

// Digits with an optional single decimal point, and at least one digit.
// Examples that match: "1250", "1250.5", ".5", "12.", "007".
const DECIMAL_TEXT = /^(\d*)(?:\.(\d*))?$/;

/**
 * Split decimal text into its whole and fraction digit strings.
 * Returns null when the text is not digits with an optional single decimal point.
 * @param {string} text already trimmed
 * @returns {{whole: string, fraction: string} | null}
 */
export function splitDecimal(text) {
  const match = DECIMAL_TEXT.exec(text);
  if (!match) return null;
  const whole = match[1];
  const fraction = match[2] ?? '';
  if (whole === '' && fraction === '') return null; // "." or "" has no digits
  return { whole, fraction };
}

/**
 * Convert whole and fraction digit strings (fraction at most 2 digits)
 * into a BigInt count of hundredths. Used for cents and for tip percentages
 * in hundredths of a percent.
 * @returns {bigint}
 */
export function toHundredths({ whole, fraction }) {
  const wholePart = BigInt(whole === '' ? '0' : whole);
  const fractionPart = BigInt((fraction + '00').slice(0, 2));
  return wholePart * 100n + fractionPart;
}

/** Insert a comma every three digits in a string of digits. */
function groupThousands(digits) {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

/**
 * Format BigInt cents as "1,260.00". Grouping is done by hand rather than
 * with toLocaleString, so the output never depends on the browser's language.
 * @param {bigint} cents
 * @returns {string}
 */
export function formatCents(cents) {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const whole = (abs / 100n).toString();
  const fraction = (abs % 100n).toString().padStart(2, '0');
  return `${negative ? '-' : ''}${groupThousands(whole)}.${fraction}`;
}

/**
 * Format a tip percentage held in hundredths of a percent, without trailing
 * decimal zeros: 1250n → "12.5", 700n → "7", 10n → "0.1", 1n → "0.01".
 * @param {bigint} hundredths
 * @returns {string}
 */
export function formatPercent(hundredths) {
  const whole = (hundredths / 100n).toString();
  const fraction = (hundredths % 100n).toString().padStart(2, '0').replace(/0+$/, '');
  return fraction === '' ? whole : `${whole}.${fraction}`;
}

// Parsing and validation for every kind of input, with the message
// precedence orders from the shared definitions in docs/user-stories.md.
// Every function returns { ok: true, value } or { ok: false, message },
// or { ok: true, empty: true } for an optional field left empty.

import { splitDecimal, toHundredths } from './money.js';
import * as M from './messages.js';

const MAX_CENTS = 100_000_000n; // 1,000,000.00

// A comma or currency symbol anywhere, or a currency code at the start or end,
// in any letter case, with or without a space (shared definitions: "Money inputs").
const CURRENCY_SYMBOL_OR_COMMA = /[,$€£₹₨]/;
const CURRENCY_CODE_AT_START = /^(rs\.?|pkr)/i;
const CURRENCY_CODE_AT_END = /(rs\.?|pkr)$/i;

function hasCommaOrCurrency(text) {
  return (
    CURRENCY_SYMBOL_OR_COMMA.test(text) ||
    CURRENCY_CODE_AT_START.test(text) ||
    CURRENCY_CODE_AT_END.test(text)
  );
}

/**
 * Validate a money input.
 * @param {string} raw the text exactly as typed
 * @param {'subtotal'|'tax'|'ordered'} kind which field, which sets the empty
 *   and minimum rules
 */
export function parseMoney(raw, kind) {
  const text = raw.trim();

  // 1. empty
  if (text === '') {
    if (kind === 'tax') return { ok: true, value: 0n, empty: true };
    return { ok: false, message: kind === 'subtotal' ? M.SUBTOTAL_EMPTY : M.ORDERED_MIN, empty: true };
  }
  // 2. comma or currency symbol
  if (hasCommaOrCurrency(text)) return { ok: false, message: M.COMMA_OR_CURRENCY };
  // 3. negative
  if (text.startsWith('-')) return { ok: false, message: M.NEGATIVE };
  // 4. not a valid number
  const parts = splitDecimal(text);
  if (!parts) return { ok: false, message: M.NOT_A_NUMBER };
  // 5. more than 2 decimal places
  if (parts.fraction.length > 2) return { ok: false, message: M.TOO_MANY_DECIMALS };

  const cents = toHundredths(parts);
  // 6. below the minimum
  if (kind === 'subtotal' && cents < 1n) return { ok: false, message: M.SUBTOTAL_MIN };
  if (kind === 'ordered' && cents < 1n) return { ok: false, message: M.ORDERED_MIN };
  // 7. above the maximum
  if (cents > MAX_CENTS) return { ok: false, message: M.AMOUNT_MAX };

  return { ok: true, value: cents };
}

/**
 * Validate a custom tip. Returns the tip in hundredths of a percent (BigInt).
 * Precedence: empty → not a number → more than 2 decimals → above 100.
 */
export function parseTip(raw) {
  let text = raw.trim();
  // 1. empty
  if (text === '') return { ok: false, message: M.TIP_EMPTY, empty: true };
  // A single trailing % is ignored, as are spaces around the value.
  if (text.endsWith('%')) text = text.slice(0, -1).trim();
  // 2. not a number: anything other than digits with an optional single decimal point
  const parts = splitDecimal(text);
  if (!parts) return { ok: false, message: M.TIP_RANGE };
  // 3. more than 2 decimal places
  if (parts.fraction.length > 2) return { ok: false, message: M.TOO_MANY_DECIMALS };
  // 4. above 100
  const hundredths = toHundredths(parts);
  if (hundredths > 10_000n) return { ok: false, message: M.TIP_RANGE };
  return { ok: true, value: hundredths };
}

/**
 * Validate the number of people: digits only, from 1 to 50. Leading zeros are
 * allowed. Returns a BigInt count.
 */
export function parsePeople(raw) {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return { ok: false, message: M.PEOPLE_INVALID, empty: text === '' };
  const count = BigInt(text);
  if (count < 1n || count > 50n) return { ok: false, message: M.PEOPLE_INVALID };
  return { ok: true, value: count };
}

/**
 * The label for a person's row: the trimmed name, or "Person N" (N = position,
 * starting at 1) when the name is empty or only spaces.
 */
export function personLabel(rawName, position) {
  const name = (rawName ?? '').trim();
  return name === '' ? M.defaultPersonLabel(position) : name;
}

// The arithmetic. Every argument and result is a BigInt count of cents
// (or hundredths of a percent for the tip). No floating-point numbers (D-19).

/**
 * Tip on the subtotal, rounded to the nearest cent with exact halves rounded
 * up (D-3). All values are zero or positive, so adding half the divisor before
 * BigInt's truncating division rounds half up.
 * @param {bigint} subtotalCents
 * @param {bigint} tipHundredths tip percentage in hundredths of a percent (1250n = 12.5%)
 */
export function tipCents(subtotalCents, tipHundredths) {
  return (subtotalCents * tipHundredths + 5_000n) / 10_000n;
}

/**
 * Split a total evenly between `count` people (D-4).
 * `higherCount` people pay `base + 1` cent and the rest pay `base`, so the
 * shares always add up exactly to the total.
 * @returns {{ base: bigint, higherCount: bigint, lowerCount: bigint }}
 */
export function evenSplit(totalCents, count) {
  const base = totalCents / count;
  const higherCount = totalCents % count;
  return { base, higherCount, lowerCount: count - higherCount };
}

/**
 * Share `extraCents` (tax and service charges plus tip) between people in
 * proportion to what each ordered (D-5).
 *
 * Each share is rounded down to the cent. The cents left over go one at a time
 * to the people with the largest remainders; ties go to the person higher in
 * the list. The products extra × ordered can exceed 2^53, which is why this
 * must be BigInt: with ordinary numbers the remainders come out slightly
 * wrong and a leftover cent can go to the wrong person (criterion S-6.10).
 *
 * @param {bigint[]} orderedCents each person's ordered amount, every one at least 1n
 * @param {bigint} extraCents
 * @returns {bigint[]} each person's share of the extra, in list order
 */
export function allocateExtra(orderedCents, extraCents) {
  const sum = orderedCents.reduce((a, b) => a + b, 0n);
  const shares = orderedCents.map((o) => (extraCents * o) / sum);
  const remainders = orderedCents.map((o) => (extraCents * o) % sum);

  let leftover = extraCents - shares.reduce((a, b) => a + b, 0n);
  const order = orderedCents
    .map((_, index) => index)
    .sort((a, b) => {
      if (remainders[a] !== remainders[b]) return remainders[a] > remainders[b] ? -1 : 1;
      return a - b; // tie: higher in the list first
    });
  for (const index of order) {
    if (leftover === 0n) break;
    shares[index] += 1n;
    leftover -= 1n;
  }
  return shares;
}

// The engine: turns the raw state of the form into everything the screen
// shows: which fields are outlined, which messages appear, and the exact
// result lines. It is pure: no DOM, no side effects. The UI only copies its
// output onto the page (technical plan: "Architecture").

import { parseMoney, parseTip, parsePeople, personLabel } from './validate.js';
import { tipCents, evenSplit, allocateExtra } from './calc.js';
import { formatCents, formatPercent } from './money.js';
import * as M from './messages.js';

export const MAX_ROWS = 50;
export const TIP_PRESETS = ['0', '10', '15', '20'];

/**
 * The state of the form.
 * @typedef {{ id: number, name: string, ordered: string }} Row
 * @typedef {{
 *   mode: 'even' | 'order',
 *   subtotal: string, tax: string,
 *   tipChoice: '0' | '10' | '15' | '20' | 'custom', customTip: string,
 *   people: string,
 *   rows: Row[], nextRowId: number,
 *   left: Record<string, boolean>
 * }} State
 * `left` records which fields the user has left at least once. Keys are
 * 'subtotal', 'tax', 'customTip', 'people' and 'ordered:<row id>'.
 */

/** The state when the page opens (S-1.1). */
export function initialState() {
  return {
    mode: 'even',
    subtotal: '',
    tax: '',
    tipChoice: '10',
    customTip: '',
    people: '2',
    rows: [
      { id: 1, name: '', ordered: '' },
      { id: 2, name: '', ordered: '' },
    ],
    nextRowId: 3,
    left: {},
  };
}

/** Reset: everything back to the opening state, keeping the current mode (D-12). */
export function resetState(state) {
  return { ...initialState(), mode: state.mode };
}

/** Add an empty unnamed row at the end of the list, up to 50 rows. */
export function addRow(state) {
  if (state.rows.length >= MAX_ROWS) return state;
  return {
    ...state,
    rows: [...state.rows, { id: state.nextRowId, name: '', ordered: '' }],
    nextRowId: state.nextRowId + 1,
  };
}

/** Remove a row by id. The last remaining row cannot be removed. */
export function removeRow(state, id) {
  if (state.rows.length <= 1) return state;
  const left = { ...state.left };
  delete left[`ordered:${id}`];
  return { ...state, rows: state.rows.filter((row) => row.id !== id), left };
}

/** Field status from a validation result and whether the user has left the field. */
function fieldStatus(result, hasLeft) {
  if (result.ok) return { invalid: false, message: null, waiting: false };
  // A required field that is empty and has never been left is not an error yet.
  if (result.empty && !hasLeft) return { invalid: false, message: null, waiting: true };
  // An invalid value is outlined straight away; its message appears once the field has been left.
  return { invalid: true, message: hasLeft ? result.message : null, waiting: false };
}

const CLEAR = { invalid: false, message: null, waiting: false };

/**
 * Compute everything the screen shows for a given state.
 * @param {State} state
 */
export function compute(state) {
  const left = state.left ?? {};
  const fields = { subtotal: CLEAR, tax: CLEAR, customTip: CLEAR, people: CLEAR };

  // Receipt fields, shared by both modes.
  const subtotal = parseMoney(state.subtotal, 'subtotal');
  fields.subtotal = fieldStatus(subtotal, left.subtotal);
  const tax = parseMoney(state.tax, 'tax');
  fields.tax = fieldStatus(tax, left.tax);

  let tip;
  if (state.tipChoice === 'custom') {
    tip = parseTip(state.customTip);
    fields.customTip = fieldStatus(tip, left.customTip);
  } else {
    tip = { ok: true, value: BigInt(state.tipChoice) * 100n };
  }

  // Mode-specific fields.
  let people = null;
  const rowResults = [];
  const rows = state.rows.map((row, index) => {
    const result = parseMoney(row.ordered, 'ordered');
    rowResults.push(result);
    return {
      id: row.id,
      label: personLabel(row.name, index + 1),
      ...(state.mode === 'order' ? fieldStatus(result, left[`ordered:${row.id}`]) : CLEAR),
    };
  });
  if (state.mode === 'even') {
    people = parsePeople(state.people);
    fields.people = fieldStatus(people, left.people);
  }

  const controls = {
    canAddRow: state.rows.length < MAX_ROWS,
    canRemoveRow: state.rows.length > 1,
    addRowNote: state.rows.length >= MAX_ROWS ? M.MAX_PEOPLE_NOTE : null,
  };

  // What the results area shows.
  const statuses = [fields.subtotal, fields.tax, fields.customTip, fields.people];
  if (state.mode === 'order') statuses.push(...rows);
  const anyInvalid = statuses.some((s) => s.invalid);
  const anyWaiting = statuses.some((s) => s.waiting);

  const base = { fields, rows, controls };
  if (anyInvalid) return { ...base, resultsMessage: M.FIX_FIELDS, results: null };
  if (anyWaiting) return { ...base, resultsMessage: M.FILL_IN, results: null };

  // Every input is valid: calculate.
  const S = subtotal.value;
  const X = tax.value;
  const tipAmount = tipCents(S, tip.value);
  const T = S + X + tipAmount;
  const receipt = [
    { label: M.LABEL_SUBTOTAL, value: formatCents(S) },
    { label: M.LABEL_TAX, value: formatCents(X) },
    { label: M.labelTip(formatPercent(tip.value)), value: formatCents(tipAmount) },
    { label: M.LABEL_TOTAL, value: formatCents(T) },
  ];

  if (state.mode === 'even') {
    const n = people.value;
    const { base: share, higherCount, lowerCount } = evenSplit(T, n);
    const split =
      higherCount === 0n
        ? [M.eachPays(formatCents(share))]
        : [M.groupPays(higherCount, formatCents(share + 1n)), M.groupPays(lowerCount, formatCents(share))];
    split.push(M.sharesAddUp(n, formatCents(T)));
    return { ...base, resultsMessage: null, results: { receipt, split } };
  }

  // Split by order.
  const ordered = rowResults.map((r) => r.value);
  const shares = allocateExtra(ordered, X + tipAmount);
  const owes = ordered.map((o, i) => o + shares[i]);
  const table = rows.map((row, i) => ({
    id: row.id,
    label: row.label,
    ordered: formatCents(ordered[i]),
    share: formatCents(shares[i]),
    owes: formatCents(owes[i]),
  }));

  const A = ordered.reduce((a, b) => a + b, 0n);
  const totalOwed = owes.reduce((a, b) => a + b, 0n);
  let warning = null;
  let note;
  if (A === S) {
    note = M.MATCHES_RECEIPT;
  } else if (A < S) {
    warning = M.warningBelow(formatCents(A), formatCents(S), formatCents(S - A));
    note = M.totalBelow(formatCents(T - totalOwed), formatCents(T));
  } else {
    warning = M.warningAbove(formatCents(A), formatCents(A - S), formatCents(S));
    note = M.totalAbove(formatCents(totalOwed - T), formatCents(T));
  }

  return {
    ...base,
    resultsMessage: null,
    results: { receipt, table, totalRow: { amount: formatCents(totalOwed), note }, warning },
  };
}

// Shared helpers for the tests. This file is not itself a test file
// (node --test only runs files named *.test.js).

import { initialState } from '../src/lib/engine.js';

/** A "Split evenly" state: the opening state with some fields changed. */
export function evenState(overrides = {}) {
  return { ...initialState(), ...overrides };
}

/**
 * A "Split by order" state. `rows` is a list of ordered amounts, or of
 * [name, ordered] pairs. Rows get ids 1, 2, 3 and so on.
 */
export function orderState(overrides = {}, rows = []) {
  const built = rows.map((spec, i) =>
    Array.isArray(spec)
      ? { id: i + 1, name: spec[0], ordered: spec[1] }
      : { id: i + 1, name: '', ordered: spec },
  );
  return {
    ...initialState(),
    mode: 'order',
    rows: built,
    nextRowId: built.length + 1,
    ...overrides,
  };
}

/** The receipt lines as the user reads them, e.g. "Subtotal 1,000.00". */
export function receiptLines(output) {
  return output.results.receipt.map((line) => `${line.label} ${line.value}`);
}

/** The "Owes" column of the Split by order table. */
export function owes(output) {
  return output.results.table.map((row) => row.owes);
}

/** The "Share of tax and tip" column of the Split by order table. */
export function shares(output) {
  return output.results.table.map((row) => row.share);
}

/** The receipt line for the tip, e.g. "Tip (10%) 100.00". */
export function tipLine(output) {
  return receiptLines(output)[2];
}

/** The receipt line for the total, e.g. "Total 1,260.00". */
export function totalLine(output) {
  return receiptLines(output)[3];
}

// Money and percentage text handling. Money is BigInt cents from input to
// display (D-6, D-19), so these tests compare BigInts exactly.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { splitDecimal, toHundredths, formatCents, formatPercent } from '../src/lib/money.js';

const cents = (text) => toHundredths(splitDecimal(text));

test('D-6: 0.10 + 0.20 is exactly 0.30, with no floating-point error', () => {
  assert.equal(cents('0.1') + cents('0.2'), 30n);
  assert.equal(formatCents(cents('0.1') + cents('0.2')), '0.30');
  assert.notEqual(0.1 + 0.2, 0.3); // the floating-point problem this avoids
});

test('S-1.5: ".5", "12." and "007" read as 50, 1200 and 700 cents', () => {
  assert.equal(cents('.5'), 50n);
  assert.equal(cents('12.'), 1200n);
  assert.equal(cents('007'), 700n);
});

test('S-1.7: text that is not digits with one optional decimal point is rejected', () => {
  for (const text of ['abc', '12abc', '+5', '10.0.5', '1e15', '.', '']) {
    assert.equal(splitDecimal(text), null, text);
  }
});

test('S-1.2: amounts are shown with 2 decimal places and comma thousands separators', () => {
  assert.equal(formatCents(100000n), '1,000.00');
  assert.equal(formatCents(126000n), '1,260.00');
  assert.equal(formatCents(1n), '0.01');
  assert.equal(formatCents(0n), '0.00');
  assert.equal(formatCents(300000000n), '3,000,000.00');
});

test('S-2.6: tip percentages are shown without trailing decimal zeros', () => {
  assert.equal(formatPercent(1250n), '12.5'); // 12.50
  assert.equal(formatPercent(700n), '7'); // 007
  assert.equal(formatPercent(10n), '0.1'); // 0.10
  assert.equal(formatPercent(1n), '0.01');
  assert.equal(formatPercent(10000n), '100');
  assert.equal(formatPercent(0n), '0');
});

