// A small static file server for src/, using only Node's built-in modules.
// Browsers refuse to load JavaScript modules from a page opened directly from
// disk, so the app has to be served over HTTP (D-17, D-23).
//
// Usage: npm start            (http://localhost:8080)
//        PORT=3000 npm start  (any other port)

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(fileURLToPath(new URL('../src', import.meta.url)));
const PORT = Number.parseInt(process.env.PORT ?? '8080', 10);

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8', // must be a JavaScript type, or modules are blocked
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
};

const server = createServer(async (request, response) => {
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    response.writeHead(405, { Allow: 'GET, HEAD' }).end('Method not allowed');
    return;
  }

  let path;
  try {
    path = decodeURIComponent(new URL(request.url, 'http://localhost').pathname);
  } catch {
    response.writeHead(400).end('Bad request');
    return;
  }
  if (path.endsWith('/')) path += 'index.html';

  // Refuse anything that resolves outside src/, such as /../package.json.
  const file = resolve(ROOT, '.' + path);
  if (file !== ROOT && !file.startsWith(ROOT + sep)) {
    response.writeHead(403).end('Forbidden');
    return;
  }

  try {
    const body = await readFile(file);
    response.writeHead(200, {
      'Content-Type': TYPES[extname(file)] ?? 'application/octet-stream',
      'Cache-Control': 'no-store',
    });
    response.end(request.method === 'HEAD' ? undefined : body);
  } catch {
    response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }).end('Not found');
  }
});

server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use. Start on another port, for example: PORT=3000 npm start`);
  } else {
    console.error(`Could not start the server: ${error.message}`);
  }
  process.exit(1);
});

server.listen(PORT, () => {
  console.log(`Tip and Bill Splitter is running at http://localhost:${PORT}`);
  console.log('Press Ctrl+C to stop.');
});

:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --text: #1d2420;
  --muted: #5b6660;
  --border: #c9cec9;
  --accent: #1f6f50;
  --accent-soft: #e3f1ea;
  --error: #b3261e;
  --error-soft: #fdecea;
  --warning-bg: #fff4d6;
  --warning-border: #c98a00;
  --focus: #1f5fbf;
  --radius: 10px;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #141816;
    --surface: #1d2320;
    --text: #e9ece9;
    --muted: #a3ada7;
    --border: #3a443f;
    --accent: #5cc496;
    --accent-soft: #20372c;
    --error: #ff8a80;
    --error-soft: #3a1f1d;
    --warning-bg: #3a3017;
    --warning-border: #e0b44c;
    --focus: #8ab4ff;
    color-scheme: dark;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
}

main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1rem 1rem 3rem;
}

h1 {
  font-size: 1.6rem;
  margin: 0.5rem 0 0.25rem;
}

h2 {
  font-size: 1.1rem;
  margin: 0 0 0.75rem;
}

.intro {
  color: var(--muted);
  margin: 0 0 1rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  margin: 0 0 1rem;
}

/* Fields */
.field {
  margin: 0 0 0.75rem;
}

label {
  display: block;
  font-weight: 600;
  margin: 0 0 0.25rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input[type='text'] {
  width: 100%;
  font: inherit;
  font-size: 1.05rem; /* 16px or more stops phones zooming in on focus */
  padding: 0.6rem 0.7rem;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
}

/* "Outlined in red": an invalid value, straight away, or a field showing an error */
input[aria-invalid='true'] {
  border-color: var(--error);
  box-shadow: 0 0 0 1px var(--error);
  background: var(--error-soft);
}

.error {
  color: var(--error);
  font-size: 0.95rem;
  margin: 0.3rem 0 0;
}

.error:empty {
  display: none;
}

/* Visible focus for keyboard users */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* Segmented radio groups: mode and tip */
fieldset {
  border: 0;
  margin: 0 0 1rem;
  padding: 0;
  min-width: 0;
}

legend {
  font-weight: 600;
  padding: 0;
  margin: 0 0 0.35rem;
}

.segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.segmented legend {
  width: 100%;
}

.segmented label {
  position: relative;
  margin: 0;
  font-weight: 500;
  flex: 1 1 auto;
}

/* The radio stays in the page for the keyboard and screen readers, but is drawn as a button. */
.segmented input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}

.segmented span {
  display: block;
  text-align: center;
  padding: 0.55rem 0.8rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  white-space: nowrap;
}

.segmented input:checked + span {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--text);
  font-weight: 700;
}

.segmented input:focus-visible + span {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* Buttons */
button {
  font: inherit;
  font-weight: 600;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  cursor: pointer;
}

button.secondary {
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.actions {
  margin: 0 0 1rem;
}

/* Split by order rows */
.rows {
  list-style: none;
  margin: 0 0 0.75rem;
  padding: 0;
}

.row {
  border-top: 1px solid var(--border);
  padding: 0.75rem 0 0.25rem;
}

.row:first-child {
  border-top: 0;
  padding-top: 0;
}

.row-label {
  margin: 0 0 0.4rem;
  font-weight: 700;
}

.row-fields {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 0.5rem;
  align-items: end;
}

.row-fields .field {
  margin: 0;
  min-width: 0;
}

.add-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.note {
  margin: 0;
  color: var(--muted);
}

/* Results */
.results-message {
  margin: 0;
  color: var(--muted);
}

.results-message:empty {
  display: none;
}

.receipt {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.2rem 1rem;
  margin: 0 0 1rem;
}

.receipt dt,
.receipt dd {
  margin: 0;
}

.receipt dd {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.receipt dt:last-of-type,
.receipt dd:last-of-type {
  font-weight: 700;
  border-top: 1px solid var(--border);
  padding-top: 0.3rem;
}

.split {
  list-style: none;
  margin: 0;
  padding: 0.75rem 1rem;
  background: var(--accent-soft);
  border-radius: 8px;
  font-size: 1.1rem;
}

.split li:first-child {
  font-weight: 700;
}

.split li:last-child {
  color: var(--muted);
  font-size: 0.95rem;
  margin-top: 0.25rem;
}

.warning {
  margin: 0 0 1rem;
  padding: 0.75rem 1rem;
  background: var(--warning-bg);
  border-left: 4px solid var(--warning-border);
  border-radius: 6px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

th,
td {
  text-align: left;
  padding: 0.45rem 0.4rem;
  border-bottom: 1px solid var(--border);
  overflow-wrap: anywhere;
}

thead th {
  font-size: 0.9rem;
  color: var(--muted);
}

.num {
  text-align: right;
}

tfoot th,
tfoot td {
  font-weight: 700;
  border-bottom: 0;
}

.total-note {
  margin: 0.5rem 0 0;
  font-weight: 600;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

[hidden] {
  display: none !important;
}

/* Phone width: stack the row fields, and show the table as one card per person */
@media (max-width: 30rem) {
  .row-fields {
    grid-template-columns: 1fr 1fr;
  }

  .row-fields .remove {
    grid-column: 1 / -1;
    justify-self: start;
  }

  thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  table,
  tbody,
  tbody tr,
  tbody th,
  tbody td {
    display: block;
    width: 100%;
  }

  tbody tr {
    border-bottom: 1px solid var(--border);
    padding: 0.4rem 0;
  }

  tbody th,
  tbody td {
    border: 0;
    padding: 0.1rem 0;
  }

  tbody td {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
  }

  tbody td::before {
    content: attr(data-label);
    color: var(--muted);
    text-align: left;
  }

  tfoot tr {
    display: flex;
    justify-content: space-between;
  }

  tfoot th,
  tfoot td {
    padding: 0.5rem 0 0;
  }
}

// The UI. It keeps the form's state, runs every change through the engine,
// and copies the engine's output onto the page. It does no arithmetic and
// contains no message text: every string shown comes from src/lib (D-19, D-25).
//
// Rules from the technical plan:
// - A field the user is typing in is never recreated (D-21). Inputs are
//   written from state only on page load and on Reset; rows are created or
//   removed only when a person is added or removed.
// - Every string goes onto the page with textContent, never as HTML (D-24).

import { initialState, compute, resetState, addRow, removeRow } from './lib/engine.js';

const byId = (id) => document.getElementById(id);

const form = byId('form');
const inputs = {
  subtotal: byId('subtotal'),
  tax: byId('tax'),
  customTip: byId('customTip'),
  people: byId('people'),
};
const rowList = byId('rows');
const rowTemplate = byId('row-template');
const rowElements = new Map(); // row id → { item, label, name, ordered, remove, error }

let state = initialState();

// ---------------------------------------------------------------- events

// Pressing Enter in a field must not submit the form and reload the page.
form.addEventListener('submit', (event) => event.preventDefault());

for (const [key, input] of Object.entries(inputs)) {
  input.addEventListener('input', () => update({ [key]: input.value }));
  input.addEventListener('blur', () => markLeft(key));
}

for (const radio of form.elements.mode) {
  radio.addEventListener('change', () => update({ mode: radio.value }));
}

for (const radio of form.elements.tip) {
  radio.addEventListener('change', () => update({ tipChoice: radio.value }));
}

byId('add-row').addEventListener('click', () => {
  state = addRow(state);
  render();
  const newest = state.rows[state.rows.length - 1];
  rowElements.get(newest.id)?.name.focus();
});

byId('reset').addEventListener('click', () => {
  state = resetState(state);
  writeInputsFromState();
  render();
});

// ---------------------------------------------------------------- state changes

function update(changes) {
  state = { ...state, ...changes };
  render();
}

function markLeft(key) {
  if (!state.left[key]) state = { ...state, left: { ...state.left, [key]: true } };
  render();
}

function updateRow(id, changes) {
  state = { ...state, rows: state.rows.map((row) => (row.id === id ? { ...row, ...changes } : row)) };
  render();
}

function removeRowAndMoveFocus(id) {
  const index = state.rows.findIndex((row) => row.id === id);
  state = removeRow(state, id);
  render();
  // Keep keyboard users in the list: focus the row that took this one's place,
  // or the one before it if the last row was removed.
  const next = state.rows[Math.min(index, state.rows.length - 1)];
  rowElements.get(next.id)?.name.focus();
}

// ---------------------------------------------------------------- rows

function createRowElement(row) {
  const item = rowTemplate.content.firstElementChild.cloneNode(true);
  const label = item.querySelector('.row-label');
  const name = item.querySelector('.name');
  const ordered = item.querySelector('.ordered');
  const remove = item.querySelector('.remove');
  const error = item.querySelector('.error');

  label.id = `row-${row.id}-label`;
  name.id = `row-${row.id}-name`;
  ordered.id = `row-${row.id}-ordered`;
  error.id = `row-${row.id}-error`;
  item.querySelector('.name-label').htmlFor = name.id;
  item.querySelector('.ordered-label').htmlFor = ordered.id;
  name.setAttribute('aria-describedby', label.id);
  ordered.setAttribute('aria-describedby', `${label.id} ${error.id}`);

  name.value = row.name;
  ordered.value = row.ordered;

  name.addEventListener('input', () => updateRow(row.id, { name: name.value }));
  ordered.addEventListener('input', () => updateRow(row.id, { ordered: ordered.value }));
  ordered.addEventListener('blur', () => markLeft(`ordered:${row.id}`));
  remove.addEventListener('click', () => removeRowAndMoveFocus(row.id));

  const elements = { item, label, name, ordered, remove, error };
  rowElements.set(row.id, elements);
  return elements;
}

/** Add elements for new rows and remove elements for removed rows. Existing rows are left alone. */
function syncRowElements() {
  const ids = new Set(state.rows.map((row) => row.id));
  for (const [id, elements] of rowElements) {
    if (!ids.has(id)) {
      elements.item.remove();
      rowElements.delete(id);
    }
  }
  for (const row of state.rows) {
    if (!rowElements.has(row.id)) rowList.append(createRowElement(row).item);
  }
}

/** Write every input from state. Only used on page load and on Reset. */
function writeInputsFromState() {
  for (const [key, input] of Object.entries(inputs)) input.value = state[key];
  for (const radio of form.elements.mode) radio.checked = radio.value === state.mode;
  for (const radio of form.elements.tip) radio.checked = radio.value === state.tipChoice;
  for (const elements of rowElements.values()) elements.item.remove();
  rowElements.clear();
  syncRowElements();
}

// ---------------------------------------------------------------- rendering

function showFieldStatus(input, errorElement, status) {
  input.setAttribute('aria-invalid', status.invalid ? 'true' : 'false');
  errorElement.textContent = status.message ?? '';
}

function render() {
  const output = compute(state);

  byId('even-section').hidden = state.mode !== 'even';
  byId('order-section').hidden = state.mode !== 'order';
  byId('custom-tip-field').hidden = state.tipChoice !== 'custom';

  for (const [key, input] of Object.entries(inputs)) {
    showFieldStatus(input, byId(`${key}-error`), output.fields[key]);
  }

  syncRowElements();
  for (const row of output.rows) {
    const elements = rowElements.get(row.id);
    elements.label.textContent = row.label;
    elements.remove.setAttribute('aria-label', `Remove ${row.label}`);
    elements.remove.disabled = !output.controls.canRemoveRow;
    showFieldStatus(elements.ordered, elements.error, row);
  }
  byId('add-row').disabled = !output.controls.canAddRow;
  byId('add-row-note').textContent = output.controls.addRowNote ?? '';

  renderResults(output);
}

function renderResults(output) {
  const message = byId('results-message');
  const receipt = byId('receipt');
  const split = byId('split');
  const warning = byId('warning');
  const tableWrap = byId('table-wrap');

  if (!output.results) {
    message.textContent = output.resultsMessage;
    receipt.hidden = split.hidden = warning.hidden = tableWrap.hidden = true;
    return;
  }

  const { results } = output;
  message.textContent = '';

  receipt.replaceChildren(
    ...results.receipt.flatMap(({ label, value }) => [element('dt', label), element('dd', value)]),
  );
  receipt.hidden = false;

  if (results.split) {
    split.replaceChildren(...results.split.map((line) => element('li', line)));
    split.hidden = false;
    warning.hidden = tableWrap.hidden = true;
    return;
  }

  split.hidden = true;
  warning.textContent = results.warning ?? '';
  warning.hidden = results.warning === null;

  byId('table-body').replaceChildren(
    ...results.table.map((row) => {
      const tr = document.createElement('tr');
      const th = element('th', row.label);
      th.scope = 'row';
      tr.append(
        th,
        element('td', row.ordered, 'Ordered'),
        element('td', row.share, 'Share of tax and tip'),
        element('td', row.owes, 'Owes'),
      );
      return tr;
    }),
  );
