tests={}
for l in spec:
    m=re.match(r'\s*(✔|✖) (S-\d+\.\d+): (.*?)(?: \([\d.]+ms\))?$',l)
    if m: tests.setdefault(m.group(2),[]).append((m.group(1)=='✔', m.group(3)))
# test file per name
files={}
for f in ['tests/diner.test.js','tests/organiser.test.js','tests/calc.test.js','tests/money.test.js']:
    for m in re.finditer(r"test\('(S-\d+\.\d+): ",open(f,encoding='utf-8').read()): files.setdefault(m.group(1),set()).add(f.split('/')[1])
browser={'S-1.34','S-5.20','S-5.24','S-5.28','S-5.29'}
smoke=set(re.findall(r'^\| (S-\d+\.\d+) \|[^|]*\| smoke',open('tests/manual-checklist.md',encoding='utf-8').read(),re.M))
v1=['S-1','S-2','S-3','S-10','S-5','S-6','S-7']; backlog=['S-4','S-8','S-9']
crit=[]; story=None; titles={}
for l in doc:
    m=re.match(r'### (S-\d+): (.*)',l)
    if m: story=m.group(1); titles[story]=m.group(2); continue
    m=re.match(r'- \*\*(S-\d+\.\d+)\*\* (.*)',l)
    if m: crit.append((story,m.group(1),m.group(2)))
rows=[]; summary={}
for story,cid,text in crit:
    short=re.sub(r'\s+',' ',text); short=(short[:95]+'…') if len(short)>96 else short
    short=short.replace('|','\\|')
    if story in backlog:
        auto='—'; ev='Not built (backlog)'; state='Not built'
    else:
        t=tests.get(cid,[])
        if t:
            ok=all(p for p,_ in t)
            auto=f"{'passes' if ok else 'FAILS'}: " + '; '.join(f'`{cid}: {n}`' for _,n in t) + f" ({', '.join(sorted(files.get(cid,[])))})"
            state='Automated: pass' if ok else 'Automated: FAIL'
        else:
            auto='— (needs a real browser)'; state='Manual only'
        ev = ('Chromium check by Claude: pass' if cid in browser else '')
    hand = '—' if story in backlog else ('Chrome + Firefox (smoke)' if cid in smoke else 'Chrome')
    rows.append((story,cid,short,auto,ev,hand,state))
    s=summary.setdefault(story,{'n':0,'auto':0,'manual':0,'fail':0,'built':story not in backlog})
    s['n']+=1; s['auto']+=state=='Automated: pass'; s['manual']+=state=='Manual only'; s['fail']+=state=='Automated: FAIL'
out=['# Criteria status','',
'Generated on 18 Oct 2026 from `docs/user-stories.md`, the `npm test` output (161 tests, 161 passing) and a Chromium check of the browser-only criteria. It is evidence for the status decision; it does not change any status.','',
'**Hand check** is the pass the definition of done requires from the candidate: every v1 criterion in Chrome, and the smoke criteria in Firefox as well. **None has been done yet.**','',
'| Story | ID | Criterion (shortened) | Automated test | Other evidence | Hand check needed | Current state |','|---|---|---|---|---|---|---|']
for r in rows: out.append('| '+' | '.join(r)+' |')
out+=['','## Per story','','| Story | Criteria | Automated, passing | Manual only | Failing | Hand check done | Status |','|---|---|---|---|---|---|---|']
for st in v1+backlog:
    s=summary[st]
    status='Not implemented (not built: backlog)' if not s['built'] else 'Not implemented (awaiting hand check)'
    out.append(f"| {st}: {titles[st]} | {s['n']} | {s['auto'] if s['built'] else '—'} | {s['manual'] if s['built'] else '—'} | {s['fail'] if s['built'] else '—'} | {'—' if not s['built'] else 'No'} | {status} |")
open(SP+'criteria-status.md','w',encoding='utf-8').write('\n'.join(out)+'\n')
print(f'{len(rows)} criteria'); 
for st in v1+backlog: print(st, summary[st])
EOF

